vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
float limit, dist, struc, len; vec2 uv0, uv1; vec3 uv2; vec4 box;
const mat3 RotMat = mat3(q20,q21,q22,q23,q24,q25,q26,q27,q28);
const vec3 CamPos = vec3(q4,q5,q6);
const float myzoom = q7,  res = 128, res2 = 64, tele = q16;
const float sustain = .98 - q14, change = q14, ds = q10, tic8 = 1.0/255, ffac = q17;
vec2 fstep2 (vec2 xy) {return 1.0/res*round(res*xy);}
float GetDist(vec2 uvi) {vec2 tmp; tmp = fstep2(texture(sampler_pc_main, uvi).gb);
return 1.0 - (tmp.y + 1.0/res2*(tmp.x-.50));}
vec2 PutDist(float x) {float tmp; tmp = fstep2(1.0 - x);
return (vec2(res2*((1.0 - x)-tmp)+.5,tmp));}
float MinDist (vec2 uvi)
{
float tmp; vec4 nb; vec4 nb2; vec2 pix;
pix = (vec2(1.0)/uTexSize)*(1.0 + length(uvi-0.5)*.0);
nb.x = GetDist(uvi+pix*vec2(-1,-1));   nb.y = GetDist(uvi+pix*vec2( 1.0 ,-1));
nb.z = GetDist(uvi+pix*vec2( 1.0 , 1.0 ));     nb.w = GetDist(uvi+pix*vec2(-1, 1.0 ));
nb2.x = GetDist(uvi+pix*vec2( 0.0 ,-1));   nb2.y = GetDist(uvi+pix*vec2( 1.0 , 0.0 ));
nb2.z = GetDist(uvi+pix*vec2( 0.0 , 1.0 ));    nb2.w = GetDist(uvi+pix*vec2(-1, 0.0 ));
//Eo.S. more efficient usage of min to get min value of all 8 GetDist() calls, removes 11ALU
nb = min( nb, nb2 );
nb.xy = min( nb.xy, nb.zw );
return min( nb.x, nb.y );
}
vec3 Get1 (vec2 uvi) {return mix(GetPixel(uvi), GetBlur1(uvi),change * 2.0);}
vec4 mbox (vec3 uvi) {vec3 zz, zz0; float tmp, li;
zz = uvi; zz0 = zz+q8; li=0; int iterations = 8.0 - (dist>.8);
for (int n = 0; n <= iterations; n++) {
zz = 2.0*clamp(zz,-1, 1.0 )-zz;  tmp = dot(zz,zz);
zz *= clamp(max(.25/tmp, .25), 0.0, 1.0) * 4.0; //############
zz = ffac*zz + zz0 ;}
return vec4(zz,li);}
shader_body {uv0 = uv_orig;
uv = (uv-.5)*(1.0 - ds/(1.0 - GetBlur1(uv).xy.b)) + .5;
uv1 = (uv0-.5)*uAspect.xy*tele;
vec3 noise = fract(8.0 * texture(sampler_noise_lq,uv+rand_frame.yz));
if (noise.g > .4*rad)
{
vec3 noiseBiased = noise - vec3( 0.5, 0.5, 0.5 );
//Eo.S. combine the subtraction on noise to a single vec3
//to ensure compiler does the subtraction in a single ALU
dist = MinDist(uv) +  0.006 * (noiseBiased.x) * abs(noiseBiased.y);
}
else {dist = noise.r;}
dist = min(dist,GetDist(uv)) - ds*.8;
limit = 15 + 10.0 * dist;
float tdist = dist+.000;
uv2 = multiply(vec3(uv1*tdist,tdist)/myzoom,RotMat)+CamPos;
uv2 = (fract(uv2/8.0+.5)-.5)*8.0;
box = mbox (uv2);
len = (length(box.xyz));
struc = length(box.xz) /limit;
vec3 inside  = vec3 ((1.0 - sustain)*struc+sustain*(Get1(uv).r), PutDist(dist));
vec3 outside = Get1(uv)*vec3(sustain, 1.0 ,sustain * 0.0+1)-vec3(tic8, 0.0 ,change / 4.0*0+tic8 * 4.0*(.2+rad));
