pix = (vec2(1.0)/uTexSize)*(1.0 + length(uvi-0.5)*.0);
nb.x = GetDist(uvi+pix*vec2(-1,-1));   nb.y = GetDist(uvi+pix*vec2( 1.0 ,-1));
nb.z = GetDist(uvi+pix*vec2( 1.0 , 1.0 ));     nb.w = GetDist(uvi+pix*vec2(-1, 1.0 ));
nb2.x = GetDist(uvi+pix*vec2( 0.0 ,-1));   nb2.y = GetDist(uvi+pix*vec2( 1.0 , 0.0 ));
nb2.z = GetDist(uvi+pix*vec2( 0.0 , 1.0 ));    nb2.w = GetDist(uvi+pix*vec2(-1, 0.0 ));
//Eo.S. more efficient usage of min to get min value of all 8 GetDist() calls, removes 11ALU
nb = min( nb, nb2 );
nb.xy = min( nb.xy, nb.zw );
return min( nb.x, nb.y );
}
vec3 Get1 (vec2 uvi) {return mix(GetPixel(uvi), GetBlur1(uvi),change * 2.0);}
vec4 mbox (vec3 uvi) {vec3 zz, zz0; float tmp, li;
zz = uvi; zz0 = zz+q8; li=0; int iterations = 8.0 - (dist>.8);
for (int n = 0; n <= iterations; n++) {
zz = 2.0*clamp(zz,-1, 1.0 )-zz;  tmp = dot(zz,zz);
zz *= clamp(max(.25/tmp, .25), 0.0, 1.0) * 4.0; //############
zz = ffac*zz + zz0 ;}
