tmp = clamp01(lum(texture(sampler_noise_hq,uv2 +.03*noise4(uv2 * 4.0))-.4));}
tmp = clamp01(pow(tmp,1.2) * sign(tmp));
vec3 ret1 = vec3 (0.1,0.1,1.2-uv.y)+.07 + sat(bdist * 2.0-1.5)*tmp * 4.0;;
//ret1 = 0;
int anz = 3; float t_rel = q13*6;
for (int n=1;n<=anz;n++) {
//    int m =  n-int(t_rel);
z = 1.0 - fract(1.0*n/anz-1.0*fract(-t_rel)/anz);
inten =  (1.0 - z)*z * 2.0;
tmp = 0;
for (int k = 1; k <= 1; k++) {
uv2 = z*(uv1*(1-.1*tmp)) / 4.0-vec2(q11,q12) / 6.0;
tmp = clamp01(lum(texture(sampler_noise_hq,uv2 +.03*noise4(uv2 * 4.0))-z*.5-.3) + 0.0*struc);}
tmp = clamp01(pow(tmp, 1.0 ) * sign(tmp)) *inten*(1.0 + struc * 0.0)*q1 * 2.0;
ret1 = (ret1+struc * 4.0*q1*vec3( 1.0 ,.75,.2))*sat(1.0 - tmp) + tmp;
